local tbl1 = {
	Name = "help",
	Group = require(game:GetService("ReplicatedStorage").Modules.Resources.Enums).PermissionLevel.Admin,
}

tbl1.Args = {}
tbl1.ClientRun = function(arg1)
	arg1:Reply("Command List:")
	local var1 = arg1.Cmdr.Registry:GetCommands()
	table.sort(var1, function(arg1, arg2)
		return arg1.Name < arg2.Name
	end)

	for k1, v1 in var1, nil do
		if v1.Description then
			arg1:Reply((("%* - %*"):format(v1.Name, v1.Description)))
		else
			arg1:Reply((("%*"):format(v1.Name)))
		end
	end

	return ""
end

return tbl1

