--- ReplicatedStorage.CmdrClient.Commands.DumpUi [ModuleScript]
-- y u r i

local var1 = game:GetService("ReplicatedStorage")
local var2 = game:GetService("Players")
local tbl1 = {
	Name = "dump_ui",
	Description = "Copies every runtime ScreenGui into ReplicatedStorage.RuntimeGuiDump so it can be saved as an rbxm",
	Group = require(var1.Modules.Resources.Enums).PermissionLevel.Admin,
}

tbl1.Args = {}
tbl1.ClientRun = function()
	local var4 = var1:FindFirstChild("RuntimeGuiDump")
	local var5 = var2.LocalPlayer:WaitForChild("PlayerGui")
	if var4 then
		var4:Destroy()
	end

	local var6 = Instance.new("Folder")
	var6.Name = "RuntimeGuiDump"
	local num1 = 0
	for k1, v1 in var5:GetChildren() do
		if not v1:IsA("ScreenGui") then
			continue
		end

		v1.Archivable = true
		for k2, v2 in v1:GetDescendants() do
			v2.Archivable = true
		end

		local var7 = v1:Clone()
		var7.Enabled = true
		var7.Parent = var6
		num1 = num1 + 1
	end

	var6.Parent = var1
	return (("Copied %* guis into ReplicatedStorage.RuntimeGuiDump, right click it and Save to File"):format(num1))
end

return tbl1

