local function createEntries(arg1, arg2)
	local tbl1 = {}
	for i1 = 1, arg2 do
		local tbl2 = { UserId = i1, DisplayName = ("TestPlayer%*"):format(i1) }
		tbl2.Value = if arg1.Ascending then i1 * 7.5 + 90 else (arg2 - i1 + 1) * 137
		table.insert(tbl1, tbl2)
	end

	return tbl1
end

tbl1.ClientRun = function(_, arg2)
	local var3 = arg2
	local var4 = math.clamp(var3 or var2.MAX_ENTRIES, 1, var2.MAX_ENTRIES)
	local var5 = require(var1.Controllers.LeaderboardController)
	for k1, v1 in var2.Boards, nil do
		var5.ShowEntries(v1.Name, (createEntries(v1, var4)))
